mapper.select:
SELECT cp.card_product_id, cp.card_name, cp.card_image_url, c.category_id, c.category_name, bs.value_type, bs.value_number AS discountRate, bs.point_currency_id, pc.krw_per_point, bt.min_prev_month_spend, bl.limit_value, bl.limit_basis FROM benefit_service bs JOIN service_category sc ON bs.service_id = sc.service_id JOIN category c ON sc.category_id = c.category_id JOIN card_product cp ON bs.card_product_id = cp.card_product_id LEFT JOIN point_currency pc ON bs.point_currency_id = pc.point_currency_id LEFT JOIN benefit_tier bt ON bt.tier_id = ( SELECT bt2.tier_id FROM benefit_tier bt2 WHERE bt2.service_id = bs.service_id OR bt2.plan_group_id = bs.plan_group_id ORDER BY bt2.min_prev_month_spend ASC, bt2.tier_id ASC LIMIT 1 ) LEFT JOIN benefit_limit bl ON bl.limit_id = ( SELECT bl2.limit_id FROM benefit_limit bl2 WHERE bl2.tier_id = bt.tier_id AND bl2.limit_period = 'MONTH' AND bl2.limit_basis <> 'COUNT' ORDER BY bl2.limit_id ASC LIMIT 1 ) WHERE c.category_id IN
#{categoryId}
AND cp.card_product_id NOT IN ( SELECT card_product_id FROM user_card WHERE user_id = #{userId} )
